package com.reg21meme.dross.boss.huntsman.trophy.client;

import com.reg21meme.dross.Dross;
import net.minecraft.resources.ResourceLocation;
import software.bernie.geckolib.core.animatable.GeoAnimatable;
import software.bernie.geckolib.model.GeoModel;

/**
 * The Huntsman trophy's files, all generated by {@code tools/huntsman/trophies.py}: the Alpha Moose's model with his
 * in the saddle, his on foot and the ice spikes beside it (its own copies, {@code geo/block/huntsman_trophy.geo.json}
 * for the placed trophy and {@code geo/item/huntsman_trophy.geo.json} for the item: GeckoLib shares a model's bones
 * between everything drawn with it, so the bosses, the placed trophies and the items each get their own), the five
 * held poses ({@code animations/block/huntsman_trophy}) and the trophy's own 512 x 512 textures (their texels side by
 * side): the solid parts, their glow, the clear ice and the ice's glow.
 */
public class HuntsmanTrophyGeoModel<T extends GeoAnimatable> extends GeoModel<T>
{
    public static final ResourceLocation BLOCK_MODEL = new ResourceLocation(Dross.MODID, "geo/block/huntsman_trophy.geo.json");
    public static final ResourceLocation ITEM_MODEL = new ResourceLocation(Dross.MODID, "geo/item/huntsman_trophy.geo.json");
    public static final ResourceLocation ANIMATIONS = new ResourceLocation(Dross.MODID, "animations/block/huntsman_trophy.animation.json");
    /** The trophy's textures: the solid parts, their glow, the clear ice and the ice's own glow. */
    public static final ResourceLocation TEXTURE = texture("");
    public static final ResourceLocation GLOW = texture("_glow");
    public static final ResourceLocation ICE = texture("_ice");
    public static final ResourceLocation ICE_GLOW = texture("_iceglow");

    private static ResourceLocation texture(String suffix)
    {
        return new ResourceLocation(Dross.MODID, "textures/block/huntsman_trophy/huntsman_trophy" + suffix + ".png");
    }

    private final ResourceLocation model;

    /** @param model {@link #BLOCK_MODEL} or {@link #ITEM_MODEL} */
    public HuntsmanTrophyGeoModel(ResourceLocation model)
    {
        this.model = model;
    }

    @Override
    public ResourceLocation getModelResource(T animatable)
    {
        return this.model;
    }

    @Override
    public ResourceLocation getTextureResource(T animatable)
    {
        return TEXTURE;
    }

    @Override
    public ResourceLocation getAnimationResource(T animatable)
    {
        return ANIMATIONS;
    }
}
